#define MOD 1000000007

long long modpow(long long a, long long e) {
    long long res = 1;
    while (e) {
        if (e & 1) res = res * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return res;
}

long long fact[300005], invfact[300005];

void precompute_fact(int n) {
    fact[0] = 1;
    for (int i = 1; i <= n; i++) fact[i] = fact[i-1] * i % MOD;
    invfact[n] = modpow(fact[n], MOD-2);
    for (int i = n-1; i >= 0; i--) invfact[i] = invfact[i+1] * (i+1) % MOD;
}

long long comb(int n, int k) {
    if (k < 0 || k > n) return 0;
    return fact[n] * invfact[k] % MOD * invfact[n-k] % MOD;
}

int parent[300005], sz[300005];

int find(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

void unite(int a, int b) {
    a = find(a); b = find(b);
    if (a == b) return;
    if (sz[a] < sz[b]) { int t = a; a = b; b = t; }
    parent[b] = a;
    sz[a] += sz[b];
}

int main() {
    int N, G, B;
    scanf("%d %d %d", &N, &G, &B);
    int total = 3 * N;
    precompute_fact(total);

    for (int i = 1; i <= total; i++) {
        parent[i] = i;
        sz[i] = 1;
    }

    for (int i = 0; i < G; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        unite(u, v);
    }

    for (int i = 0; i < B; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        if (find(u) == find(v)) {
            printf("0\n");
            return 0;
        }
    }

    int comp_size_count[4] = {0};
    int visited[300005] = {0};

    for (int i = 1; i <= total; i++) {
        int root = find(i);
        if (!visited[root]) {
            visited[root] = 1;
            int s = sz[root];
            if (s > 3) {
                printf("0\n");
                return 0;
            }
            comp_size_count[s]++;
        }
    }

    int a = comp_size_count[1];
    int b = comp_size_count[2];
    int c = comp_size_count[3];

    if (b > a) {
        printf("0\n");
        return 0;
    }

    int rem = a - b;
    if (rem % 3 != 0) {
        printf("0\n");
        return 0;
    }

    long long ans = comb(a, b) * fact[b] % MOD;
    int groups = rem / 3;
    // ways to partition rem into groups of 3
    long long ways = fact[rem];
    long long denom = modpow(6, groups) * fact[groups] % MOD;
    ways = ways * modpow(denom, MOD-2) % MOD;
    ans = ans * ways % MOD;

    printf("%lld\n", ans);
    return 0;
}

