#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXM 1000000

typedef long long ll;

/*
Assumed input format:
N M1 M2
Then M1 lines: a b   (good relationship: must be in same team)
Then M2 lines: a b   (bad relationship: must be in different teams)

Students are numbered 1..3N.

We count partitions into teams of size 3, where:
- all "good" edges force same team
- all "bad" edges force different teams

Two assignments differ only by which pairs are together, so team labels are irrelevant.
*/

static int *parent_, *sz_;

int find_set(int x) {
    if (parent_[x] == x) return x;
    parent_[x] = find_set(parent_[x]);
    return parent_[x];
}

int union_set(int a, int b) {
    a = find_set(a);
    b = find_set(b);
    if (a == b) return 1;
    if (sz_[a] < sz_[b]) {
        int t = a; a = b; b = t;
    }
    parent_[b] = a;
    sz_[a] += sz_[b];
    return 1;
}

typedef struct {
    int u, v;
} Edge;

static Edge *bad_edges;

static int *roots;
static int *comp_id;
static int *comp_size;

static unsigned char *badmat;

static ll ans = 0;

static int c1, c2, c3;
static int total_comps;

/* memo for DFS by counts of remaining components of size 1 and 2.
   size-3 components are forced single teams and removed beforehand. */
static ll *memo;
static int memoW2, memoW3;
static unsigned char *vis;

static inline ll encode_state(int a, int b, int c) {
    return ((ll)a * memoW2 + b) * memoW3 + c;
}

static ll dfs(int a, int b, int c);

/* Component lists by size */
static int *list1, *list2, *list3;
static int n1, n2, n3;

/* adjacency among components */
static inline int bad_between(int x, int y) {
    return badmat[(ll)x * total_comps + y];
}

static ll solve_by_components() {
    /* Any component > 3 impossible */
    for (int i = 0; i < total_comps; i++) {
        if (comp_size[i] > 3) return 0;
    }

    /* size-3 components are already complete teams.
       Need to count ways to partition size-1 and size-2 components into triples:
       - three size1
       - one size1 + one size2
       subject to bad constraints between chosen components.
    */
    n1 = n2 = n3 = 0;
    list1 = (int*)malloc(total_comps * sizeof(int));
    list2 = (int*)malloc(total_comps * sizeof(int));
    list3 = (int*)malloc(total_comps * sizeof(int));
    for (int i = 0; i < total_comps; i++) {
        if (comp_size[i] == 1) list1[n1++] = i;
        else if (comp_size[i] == 2) list2[n2++] = i;
        else if (comp_size[i] == 3) list3[n3++] = i;
    }

    /* Necessary divisibility */
    if ((n1 + 2 * n2) % 3 != 0) {
        free(list1); free(list2); free(list3);
        return 0;
    }

    /* Backtracking over actual unused components.
       Since exact constraints matter, count by recursive search.
    */
    unsigned char *used = (unsigned char*)calloc(total_comps, 1);

    ll res = 0;

    /* recursive lambda replacement */
    struct FrameDummy { int dummy; };

    ll rec(void) {
        int first = -1;
        for (int i = 0; i < total_comps; i++) {
            if (comp_size[i] < 3 && !used[i]) {
                first = i;
                break;
            }
        }
        if (first == -1) return 1;

        ll ways = 0;
        used[first] = 1;

        if (comp_size[first] == 2) {
            /* must pair with one size-1 component not bad */
            for (int j = 0; j < total_comps; j++) {
                if (!used[j] && comp_size[j] == 1 && !bad_between(first, j)) {
                    used[j] = 1;
                    ways += rec();
                    used[j] = 0;
                }
            }
        } else {
            /* first is size 1 */
            /* option 1: pair with one size-2 */
            for (int j = 0; j < total_comps; j++) {
                if (!used[j] && comp_size[j] == 2 && !bad_between(first, j)) {
                    used[j] = 1;
                    ways += rec();
                    used[j] = 0;
                }
            }
            /* option 2: three size-1 components. To avoid duplicates, choose j<k after first */
            for (int j = first + 1; j < total_comps; j++) {
                if (!used[j] && comp_size[j] == 1 && !bad_between(first, j)) {
                    used[j] = 1;
                    for (int k = j + 1; k < total_comps; k++) {
                        if (!used[k] && comp_size[k] == 1 &&
                            !bad_between(first, k) && !bad_between(j, k)) {
                            used[k] = 1;
                            ways += rec();
                            used[k] = 0;
                        }
                    }
                    used[j] = 0;
                }
            }
        }

        used[first] = 0;
        return ways;
    }

    res = rec();

    free(used);
    free(list1); free(list2); free(list3);
    return res;
}

int main(void) {
    int N, M1, M2;
    if (scanf("%d %d %d", &N, &M1, &M2) != 3) return 0;

    int S = 3 * N;

    parent_ = (int*)malloc((S + 1) * sizeof(int));
    sz_ = (int*)malloc((S + 1) * sizeof(int));
    for (int i = 1; i <= S; i++) {
        parent_[i] = i;
        sz_[i] = 1;
    }

    for (int i = 0; i < M1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        union_set(a, b);
    }

    bad_edges = (Edge*)malloc((M2 + 5) * sizeof(Edge));
    for (int i = 0; i < M2; i++) {
        scanf("%d %d", &bad_edges[i].u, &bad_edges[i].v);
    }

    roots = (int*)malloc((S + 1) * sizeof(int));
    comp_id = (int*)malloc((S + 1) * sizeof(int));
    memset(comp_id, -1, (S + 1) * sizeof(int));

    total_comps = 0;
    for (int i = 1; i <= S; i++) {
        int r = find_set(i);
        if (comp_id[r] == -1) {
            comp_id[r] = total_comps;
            roots[total_comps++] = r;
        }
    }

    comp_size = (int*)malloc(total_comps * sizeof(int));
    for (int i = 0; i < total_comps; i++) comp_size[i] = sz_[roots[i]];

    for (int i = 0; i < M2; i++) {
        int a = bad_edges[i].u, b = bad_edges[i].v;
        int ca = comp_id[find_set(a)];
        int cb = comp_id[find_set(b)];
        if (ca == cb) {
            /* same good-component but must be different => impossible */
            printf("0\n");
            free(parent_); free(sz_); free(bad_edges); free(roots); free(comp_id); free(comp_size);
            return 0;
        }
    }

    badmat = (unsigned char*)calloc((ll)total_comps * total_comps, 1);
    for (int i = 0; i < M2; i++) {
        int ca = comp_id[find_set(bad_edges[i].u)];
        int cb = comp_id[find_set(bad_edges[i].v)];
        badmat[(ll)ca * total_comps + cb] = 1;
        badmat[(ll)cb * total_comps + ca] = 1;
    }

    ll result = solve_by_components();
    printf("%lld\n", result);

    free(parent_);
    free(sz_);
    free(bad_edges);
    free(roots);
    free(comp_id);
    free(comp_size);
    free(badmat);

    return 0;
}

