#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct DSU {
    vector<int> p, sz;
    DSU(int n = 0) { init(n); }
    void init(int n) {
        p.resize(n);
        sz.assign(n, 1);
        iota(p.begin(), p.end(), 0);
    }
    int find(int x) {
        if (p[x] == x) return x;
        return p[x] = find(p[x]);
    }
    bool unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return false;
        if (sz[a] < sz[b]) swap(a, b);
        p[b] = a;
        sz[a] += sz[b];
        return true;
    }
    int size(int x) { return sz[find(x)]; }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Mgood, Mbad;
    cin >> N >> Mgood >> Mbad;
    int S = 3 * N;

    DSU dsu(S);
    for (int i = 0; i < Mgood; ++i) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        dsu.unite(a, b);
    }

    vector<pair<int,int>> badRaw(Mbad);
    for (int i = 0; i < Mbad; ++i) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        badRaw[i] = {a, b};
    }

    // Compress good-relationship components.
    unordered_map<int,int> id;
    vector<int> compSize;
    vector<int> rootOf(S, -1);

    for (int i = 0; i < S; ++i) {
        int r = dsu.find(i);
        if (!id.count(r)) {
            int idx = (int)compSize.size();
            id[r] = idx;
            compSize.push_back(dsu.sz[r]);
        }
        rootOf[i] = id[r];
    }

    int C = (int)compSize.size();

    // Any good-component larger than 3 makes it impossible.
    for (int s : compSize) {
        if (s > 3) {
            cout << 0 << '\n';
            return 0;
        }
    }

    vector<vector<int>> bad(C, vector<int>(C, 0));
    for (auto [a, b] : badRaw) {
        int x = rootOf[a], y = rootOf[b];
        if (x == y) {
            // Same good component but must be different teams: impossible.
            cout << 0 << '\n';
            return 0;
        }
        bad[x][y] = bad[y][x] = 1;
    }

    // Count components of size 1,2,3.
    vector<int> ones, twos, threes;
    for (int i = 0; i < C; ++i) {
        if (compSize[i] == 1) ones.push_back(i);
        else if (compSize[i] == 2) twos.push_back(i);
        else threes.push_back(i);
    }

    // Size-3 components already form fixed teams; just ignore them.
    // We need to partition size-2 and size-1 components into groups summing to 3:
    // - one size-2 + one size-1
    // - three size-1

    int A = (int)twos.size();
    int B = (int)ones.size();

    // For each size-2 component, list compatible size-1 components.
    vector<int> okMask(A, 0);
    for (int i = 0; i < A; ++i) {
        int u = twos[i];
        int mask = 0;
        for (int j = 0; j < B; ++j) {
            int v = ones[j];
            if (!bad[u][v]) mask |= (1 << j);
        }
        okMask[i] = mask;
    }

    // If too many singletons for bitmask DP, constraints of original problem are expected small.
    // DP over used size-1 components after assigning all size-2 components.
    unordered_map<int, ll> dp, ndp;
    dp.reserve(1 << min(B, 20));
    dp[0] = 1;

    for (int i = 0; i < A; ++i) {
        ndp.clear();
        for (auto &it : dp) {
            int mask = it.first;
            ll ways = it.second;
            int avail = okMask[i] & (~mask);
            for (int j = 0; j < B; ++j) {
                if (avail & (1 << j)) {
                    ndp[mask | (1 << j)] += ways;
                }
            }
        }
        dp.swap(ndp);
    }

    ll answer = 0;

    // Precompute which triples of size-1 components are mutually compatible.
    vector<tuple<int,int,int>> goodTriples;
    for (int i = 0; i < B; ++i) {
        for (int j = i + 1; j < B; ++j) {
            if (bad[ones[i]][ones[j]]) continue;
            for (int k = j + 1; k < B; ++k) {
                if (!bad[ones[i]][ones[k]] && !bad[ones[j]][ones[k]]) {
                    goodTriples.emplace_back(i, j, k);
                }
            }
        }
    }

    // Memo for counting partitions of remaining singletons into compatible triples.
    unordered_map<int, ll> memo;
    function<ll(int)> solveTriples = [&](int remMask) -> ll {
        if (remMask == 0) return 1;
        auto it = memo.find(remMask);
        if (it != memo.end()) return it->second;

        int first = __builtin_ctz(remMask);
        ll res = 0;
        for (int j = first + 1; j < B; ++j) if (remMask & (1 << j)) {
            if (bad[ones[first]][ones[j]]) continue;
            for (int k = j + 1; k < B; ++k) if (remMask & (1 << k)) {
                if (bad[ones[first]][ones[k]] || bad[ones[j]][ones[k]]) continue;
                int nmask = remMask ^ (1 << first) ^ (1 << j) ^ (1 << k);
                res += solveTriples(nmask);
            }
        }
        memo[remMask] = res;
        return res;
    };

    int fullMask = (B == 32 ? -1 : ((1 << B) - 1));

    for (auto &it : dp) {
        int used = it.first;
        ll waysAssignTwos = it.second;
        int rem = fullMask ^ used;
        if (__builtin_popcount((unsigned)rem) % 3 != 0) continue;
        ll waysTriples = solveTriples(rem);
        answer += waysAssignTwos * waysTriples;
    }

    cout << answer << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

class UnionFind {
public:
    vector<int> parent, rank, size;
    UnionFind(int n) {
        parent.resize(n);
        rank.resize(n, 0);
        size.resize(n, 1);
        for (int i = 0; i < n; i++) parent[i] = i;
    }
    int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]);
        return parent[x];
    }
    bool unite(int x, int y) {
        int px = find(x), py = find(y);
        if (px == py) return false;
        if (rank[px] < rank[py]) swap(px, py);
        parent[py] = px;
        size[px] += size[py];
        if (rank[px] == rank[py]) rank[px]++;
        return true;
    }
    int getSize(int x) {
        return size[find(x)];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, G, B;
    cin >> N >> G >> B;
    int total = 3 * N;

    UnionFind uf(total);
    vector<vector<int>> bad(total);

    for (int i = 0; i < G; i++) {
        int u, v;
        cin >> u >> v;
        u--; v--;
        uf.unite(u, v);
    }
    for (int i = 0; i < B; i++) {
        int u, v;
        cin >> u >> v;
        u--; v--;
        bad[u].push_back(v);
        bad[v].push_back(u);
    }

    // Check consistency: if any bad pair is in same component -> impossible
    for (int u = 0; u < total; u++) {
        for (int v : bad[u]) {
            if (uf.find(u) == uf.find(v)) {
                cout << 0 << "\n";
                return 0;
            }
        }
    }

    // Compress components
    map<int, int> compId;
    vector<int> compSize;
    for (int i = 0; i < total; i++) {
        int root = uf.find(i);
        if (compId.find(root) == compId.end()) {
            compId[root] = compSize.size();
            compSize.push_back(uf.getSize(i));
        }
    }
    int C = compSize.size();

    // Build graph of components with bad relations
    vector<vector<int>> badComp(C);
    set<pair<int,int>> seen;
    for (int u = 0; u < total; u++) {
        int cu = compId[uf.find(u)];
        for (int v : bad[u]) {
            int cv = compId[uf.find(v)];
            if (cu > cv) swap(cu, cv);
            if (cu != cv && seen.find({cu, cv}) == seen.end()) {
                seen.insert({cu, cv});
                badComp[cu].push_back(cv);
                badComp[cv].push_back(cu);
            }
        }
    }

    // Check if any component size > 3 -> impossible
    for (int s : compSize) {
        if (s > 3) {
            cout << 0 << "\n";
            return 0;
        }
