public class Main {
    static int[] parent, size;
    static int find(int x) { return parent[x] == x ? x : (parent[x] = find(parent[x])); }
    static void union(int a, int b) { a = find(a); b = find(b); if(a==b) return; if(size[a]<size[b]){int t=a;a=b;b=t;} parent[b]=a; size[a]+=size[b]; }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(); // 3N students
        int G = sc.nextInt(), B = sc.nextInt();
        parent = new int[n]; size = new int[n];
        for(int i=0;i<n;i++){parent[i]=i;size[i]=1;}
        boolean impossible = false;
        for(int i=0;i<G;i++){int a=sc.nextInt()-1,b=sc.nextInt()-1; union(a,b);}
        // Check sizes
        Set<Integer> compSet = new HashSet<>();
        for(int i=0;i<n;i++) compSet.add(find(i));
        for(int c:compSet) if(size[c]>3){impossible=true;}
        Set<String> badPairs = new HashSet<>();
        for(int i=0;i<B;i++){
            int a=sc.nextInt()-1,b=sc.nextInt()-1;
            int ca=find(a),cb=find(b);
            if(ca==cb){impossible=true;}
            else { int x=Math.min(ca,cb),y=Math.max(ca,cb); badPairs.add(x+","+y); }
        }
        if(impossible){System.out.println(0);return;}
        List<Integer> comps = new ArrayList<>(compSet);
        // backtrack
        boolean[] used = new boolean[comps.size()];
        System.out.println(backtrack(comps, used, badPairs, 0));
    }
    // ... backtracking
}

